import 'package:flutter/material.dart'; import '../../services/auth_service.dart'; class ProfilePage extends StatelessWidget { const ProfilePage({super.key}); @override Widget build(BuildContext c){final u=AuthService().currentUser;return Scaffold(appBar:AppBar(title:const Text('ملفي الشخصي')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('البريد: ${u?.email??''}'),const SizedBox(height:20),FilledButton(onPressed:()=>AuthService().logout().then((_){if(c.mounted)Navigator.pop(c);}),child:const Text('تسجيل الخروج'))])));}}